custom_css:
::selection {
    background: #f8d44a;
}

.header-bg-block, .header-vertical,
.header-vertical2 {
    background-color: #ffffff;
    box-shadow: 0px 1px 5px rgba(0, 0, 0, 0.05);
}
.header-color-dark .menu-wrapper .menu > li > a:hover:after {
    background-color: #1a1a1a;
    opacity: 0.8;
}
#menu-menu-top-1{
    text-align: left !important;
    padding-left: 0px;
}
.navbar-header.show-in-header,
.navbar-header{
    display:none !important;
}
.fixed-header {
    border-top: 0px;
}
.services{
    box-shadow: 0px 6px 18px #e5e5e5;
     width: 86% !important;
    margin: 0 auto !important;
}
/*content*/
.home section{
    background-position: right !important;
}
body p{
    letter-spacing:1px !important;
}
.letter-2{
    letter-spacing:2px;
}
.letter-1{
    letter-spacing:1px;
}
.initial{
    text-transform:initial !important;
}
/*header*/
.header-wrapper.header-xstore.header-color-dark{
    box-shadow: 0 0 15px 4px #f6f6f6;
    z-index: 1;
}
.courier-block .mpc-button,
.home-about-us-block .mpc-button{
    overflow:visible;
}
.courier-block .mpc-button__title:before,
.home-about-us-block .mpc-button__title:before{
    content: " ";
    width: 26px;
    display: block;
    height: 2px;
    background: #f8d44a;
    position: absolute;
    left: -14px;
    bottom: 21px;
}
.menu-main-container .menu li:last-child a:after{
    display:none;
}
.menu-main-container .menu li:last-child a:hover{
    border-color:#f8d44a;
    color:#f8d44a;
}
.menu-main-container .menu li:last-child{
    float:right !important;
}
.menu-main-container .menu li:last-child a:before{
    content: " ";
    width: 25px;
    display: block;
    height: 2px;
    background: #f8d44a;
    position: absolute;
    left: -14px;
    bottom: 17px;
}
.menu-main-container .menu li:last-child a{
    border:3px solid #000;
    margin-left:15px;
    padding-left:35px;
    padding-right:35px;
    letter-spacing:2px;
    font-size:13px;
    /*background-image: url(http://8theme.com/demo/xstore/2/delivery/wp-content/uploads/sites/6/2018/01/button-bg.png);*/
}

/*Blog*/
.single-post .share-post .menu-social-icons li a:hover{
    background: #f8d44a;
}
.single-post .share-post .menu-social-icons li a {
    padding:8px;
    width: 30px;
    height: 30px;
    background: #21201a;
    margin-left: 5px;
}
.single-post .share-post .menu-social-icons li a i {
    color:#fff;
}
.share-post {
    border-top: none;
}
.share-title{
    font-size:22px;
}
.comment-respond{
    display:none;
}
.single-post .wp-picture.blog-hover-default{
    margin-bottom:50px;
}
.single-post article{
    letter-spacing:1px;
}
.meta-post .views-count:before,
.meta-post .post-comments-count:before{
    font-size: 20px;
}
.single-post .meta-post{
    text-align:center;
    color:#f8d44a;
    font-size:20px;
    letter-spacing:1px;
}
.single-post .post-heading{
    margin:20px auto;
}
.single-post .entry-title{
    display:none;
}
.page-heading{
    margin-bottom:100px;
}
.single-post .post-categories{
    display:none;
}
.breadcrumbs {
    padding-top: 75px;
    width: 800px;
    background: #fff;
    margin: 0 auto;
}
.page-heading.bc-size-large .title {
    max-width: 800px;
    background:#fff;
    padding-bottom:75px;
}
.border-bottom{
    display: table !important;
}
.border-bottom:after{
    content:" ";
    margin: -15px 0 0 -3% !important;
    width: 105% !important;
    display: block;
    height:12px;
    background:#f8d44a;
}
.page-heading.bc-size-large .title span:after,
.title .border-bottom:after{
    content:" ";
    width:290px;
    display: block;
    height:12px;
    background:#f8d44a;
    margin:-15px auto;

}
.post-heading {
    margin-bottom: 1em;
}
article.blog-post.post-grid *{
    text-align:center !important;
}
.read-more{
    margin-top: 20px !important;
    margin:0 auto;
    color:#21201a !important;
    font-size:16px;
}
.read-more:before{
   background-color:#21201a !important; 
}
article .wp-picture .post-categories{
    background:#21201a;
    padding: 9px 25px;
}
article .wp-picture .post-categories a{
    font-size: 11px;
    font-family: Cairo;
    font-weight: 700;
    letter-spacing: 1px;
}
.post-heading h2 a{
    font-size: 24px;
    letter-spacing: 0px;
}
.meta-post{
    font-size:16px;
}
.home .post-heading h2 a{
    font-size:21px;
    letter-spacing:1px;
}
.home .meta-post{
    font-size: 18px;
}
.home .post-categories{
    display:none;
}
.home .posts-slider article > div .wp-picture {
    margin-bottom: -7px;
}
.home .grid-post-body{
    box-shadow: 0px 3px 17px 4px #f8f8f8;
    padding: 50px 25px 50px 25px;
}
.home .swiper-wrapper{
    padding-bottom:20px;
}
.home .content-article{
    letter-spacing:1px;
}
.home .posts-slider article .meta-post .post-comments-count:before {
    color:#f8d44a;
}
.read-more:hover{
    background-color:transparent !important;
    border:3px solid #f8d44a !important;
    color:#f8d44a !important;
}
.read-more{
    margin-top: 30px !important;
    background-color:transparent !important;
    border:3px solid #000 !important;
    letter-spacing:1px !important;
}
.content-article a:after{
    content: " ";
    display: block;
    height: 3px;
    width: 25px;
    background: #f8d44a;
    position: relative;
    left: 34px;
    bottom: 37px;
}
.blog .content-article a:after {
    left: 106px;
}

/*Footer*/

 footer  #menu-menu-top-2 li.current_page_item a::after,
 footer  #menu-menu-top-2 li a:hover::after{
    width: 100%;
}


 footer #menu-menu-top-2 li a::after {
    background-color: #302e2e;
    display: block;
    content: " ";
    height: 2px;
    width: 0%;
    left: 50%;
    position: absolute;
    -webkit-transition: width .3s ease-in-out;
    -moz--transition: width .3s ease-in-out;
    transition: width .3s ease-in-out;
    -webkit-transform: translateX(-50%);
    -moz-transform: translateX(-50%);
    transform: translateX(-50%);
}
.et-follow-buttons.buttons-size-normal a {
    padding: 0 12px !important;
}
footer.footer .menu-element.horizontal .menu > li > a{
    font-family:Cairo;
    font-size:16px !important;
    font-weight:600;
    position:relative !important;
    padding: 0 !important;
    border-bottom: none;
    margin: 0 20px;
    color:#21201a;
    line-height:17px;
}

.blog footer.footer,
.single-post footer.footer{
    margin-top:60px;
}

@media only screen and (max-width: 480px) {
    body .title_services{
       margin-bottom: 30px !important;
       padding-top: 70px !important; 
    }
    
    .mob-top{
        padding-top:60px;
    }
    .fixed-header {
        box-shadow: none;
        border-bottom: 1px solid #f7f7f7 !important;
     }
    body  .price-shadow .kg-block{
        width:100% !important;
    }
    .price-block  .vc_row.wpb_row .wpb_column.vc_column_container:first-child  {
        width:80%;
        float:left;
    }
    
    .map-block > .vc_column-inner{
        margin-left: 0px !important;
    }
    .price-img .vc_column-inner{
        margin-left:5px !important;
    }
    .price-block .vc_column-inner{
        padding-right: 15px !important;
    }
    .home .first-block{
        margin-bottom:60px;
    }
    body .border-block .vc_column-inner{
        padding-right: 40px !important;
    }
    .section-testimonial .vc_column-inner,
    .map-block > .vc_column-inner,
    .price-shadow > .vc_column-inner,
    .price-shadow .col-md-6{
        padding-left:15px !important;
        padding-right:15px !important;
    }
    .vc_custom_heading.letter-1.border-bottom{
        font-size: 100px !important;
        line-height:75px !important;
    }
    .video-block .vc_column-inner{
        padding-top:100px !important;
        padding-bottom:100px !important;
    }
    .responsive-margin-bottom{
        margin-bottom:30px;
    }
    .single-post .page-heading.bc-size-large .title {
       font-size: 29px;
       line-height: 39px;
    }
    .blog .content-article a:after {
       display:none;
    }
    .border-bottom {
       display: table;
       margin: 0 auto 40px auto;
    }
    .responsive-center *{
       text-align:center !important;
    }
    .global-header-xstore.et-header-not-overlap .page-heading {
       padding-top: 3.71em;
       margin-bottom: 40px;
    }
    .breadcrumbs {
       padding-top: 50px;
       width: auto;
    }
    footer.footer .text-center .vc_column-inner{
        padding-top:25px;
    }
    .social-block .vc_column-inner {
        padding-top:0 !important;
    }
    footer.footer .et-follow-buttons{
        margin-bottom:30px;
    }
    footer.footer *{
       text-align:center !important;
    }
    footer.footer .menu-element.horizontal .menu > li > a {
       padding: 0.44em 0em !important;
    }
}


@media only screen and (max-width: 1500px) {
   .content-article a:after{
    display:none;
  }
}
